	// â”€â”€ Saves (named export/import codes, kept for later) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

	private static final int MAX_SAVED_LAYOUTS = 256;

	boolean getSavesExpanded()
	{
		String val = configManager.getConfiguration(CONFIG_GROUP, "saves_expanded");
		return val == null || Boolean.parseBoolean(val);
	}

	void setSavesExpanded(boolean expanded)
	{
		configManager.setConfiguration(CONFIG_GROUP, "saves_expanded", String.valueOf(expanded));
	}

	List<SavedLayout> getSavedLayouts()
	{
		String json = configManager.getConfiguration(CONFIG_GROUP, "saved_layouts");
		if (json == null || json.isEmpty())
		{
			return new ArrayList<>();
		}
		try
		{
			List<SavedLayout> list = gson.fromJson(json, SAVED_LAYOUT_LIST);
			return list != null ? list : new ArrayList<>();
		}
		catch (Exception e)
		{
			return new ArrayList<>();
		}
	}

	private void setSavedLayouts(List<SavedLayout> layouts)
	{
		configManager.setConfiguration(CONFIG_GROUP, "saved_layouts", gson.toJson(layouts));
	}

	/** Returns false (and saves nothing) once MAX_SAVED_LAYOUTS is reached. */
	boolean addSavedLayout(String name, String code)
	{
		List<SavedLayout> layouts = getSavedLayouts();
		if (layouts.size() >= MAX_SAVED_LAYOUTS)
		{
			return false;
		}
		layouts.add(new SavedLayout(name, code));
		setSavedLayouts(layouts);
		return true;
	}

	void renameSavedLayout(int index, String newName)
	{
		List<SavedLayout> layouts = getSavedLayouts();
		if (index < 0 || index >= layouts.size())
		{
			return;
		}
		layouts.get(index).setName(newName);
		setSavedLayouts(layouts);
	}

	void removeSavedLayout(int index)
	{
		List<SavedLayout> layouts = getSavedLayouts();
		if (index < 0 || index >= layouts.size())
		{
			return;
		}
		layouts.remove(index);
		setSavedLayouts(layouts);
	}

	// â”€â”€ Helpers â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

	/** Average colors of game textures, keyed by texture id. Written only on the client thread. */
	private final Map<Integer, Integer> textureAvgCache = new HashMap<>();

	/**
	 * Average RGB of a game texture, for flat-shading textured faces in the preview.
	 * Must be called on the client thread. Returns null when the texture isn't loaded yet
	 * (not cached, so a later call can succeed).
	 */
	Integer textureAverageRgb(int textureId)
	{
		Integer cached = textureAvgCache.get(textureId);
		if (cached != null)
		{
			return cached;
		}
		int[] pixels;
		try
		{
			pixels = client.getTextureProvider().load(textureId);
		}
		catch (Exception e)
		{
			return null;
		}
		if (pixels == null)
		{
			return null;
		}
		long r = 0, g = 0, b = 0;
		int n = 0;
		for (int p : pixels)
		{
			if (p == 0)
			{
				continue; // transparent texel
			}
			r += (p >> 16) & 0xFF;
			g += (p >> 8) & 0xFF;
			b += p & 0xFF;
			n++;
		}
		if (n == 0)
		{
			return null;
		}
		int avg = (int) (r / n) << 16 | (int) (g / n) << 8 | (int) (b / n);
		textureAvgCache.put(textureId, avg);
		return avg;
	}

	private static BufferedImage buildNavIcon()
	{
		BufferedImage img = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		// simple 3-tile grid icon
		g.setColor(new Color(100, 180, 255));
		g.fillRect(1, 1, 6, 6);
		g.fillRect(9, 1, 6, 6);
		g.fillRect(1, 9, 6, 6);
		g.setColor(new Color(180, 220, 255));
		g.fillRect(9, 9, 6, 6);
		g.setColor(new Color(60, 130, 200));
		g.drawRect(1, 1, 6, 6);
		g.drawRect(9, 1, 6, 6);
		g.drawRect(1, 9, 6, 6);
		g.drawRect(9, 9, 6, 6);
		g.dispose();
		return img;
	}
}

package com.tommyknight.mapdecorator;

import lombok.EqualsAndHashCode;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

/**
 * A single user-placed object. Up to 3 may share the same tile, distinguished by stackIndex.
 */
@Value
@EqualsAndHashCode(of = {"regionId", "regionX", "regionY", "plane", "stackIndex"})
class PlacedObject
{
	int regionId;
	int regionX;
	int regionY;
	int plane;
	int objectId;
	/** RuneLiteObject orientation. S=0, W=512, N=1024, E=1536. */
	int orientation;
	/** Stack slot on this tile: 0 = first placed, 1 = second, 2 = third. */
	int stackIndex;
	/** Looping animation sequence id; <= 0 means none. Absent in pre-1.1 saves (defaults to 0). */
	int animationId;
	/** Vertical nudge in scene Z units above ground height; positive = up. Absent in pre-1.1 saves (defaults to 0). */
	int heightOffset;
	/** Sub-tile horizontal nudge in LocalPoint units (128 = 1 tile), east-west. Absent in pre-1.2 saves (defaults to 0). */
	int offsetX;
	/** Sub-tile horizontal nudge in LocalPoint units (128 = 1 tile), north-south. Absent in pre-1.2 saves (defaults to 0). */
	int offsetY;
	/** NPC id whose merged model is placed instead of objectId; <= 0 means a plain model. Absent in pre-1.1 saves (defaults to 0). */
	int npcId;
	/** Size adjustment in percent, -100..100 where 0 = normal size. Absent in pre-1.1 saves (defaults to 0). */
	int scale;
	/** Placed NPCs wander a few tiles from this spot. Absent in pre-1.1 saves (defaults to false). */
	boolean roam;
	/** Flipped left-to-right. Absent in pre-1.2 saves (defaults to false). */
	boolean mirror;
	/** Tint colour with alpha as strength; alpha 0 = no tint. Absent in pre-1.2 saves (defaults to 0). */
	int tintArgb;

	WorldPoint toWorldPoint()
	{
		return WorldPoint.fromRegion(regionId, regionX, regionY, plane);
	}

	PlacedObject withStackIndex(int newStackIndex)
	{
		return new PlacedObject(regionId, regionX, regionY, plane, objectId, orientation, newStackIndex, animationId, heightOffset, offsetX, offsetY, npcId, scale, roam, mirror, tintArgb);
	}

	/** True if this and other would look identical if placed (ignores stack slot, which is just where they sit). */
	boolean sameDecoration(PlacedObject other)
	{
		return objectId == other.objectId
			&& orientation == other.orientation
			&& animationId == other.animationId
			&& heightOffset == other.heightOffset
			&& offsetX == other.offsetX
			&& offsetY == other.offsetY
			&& npcId == other.npcId
			&& scale == other.scale
			&& roam == other.roam
			&& mirror == other.mirror
			&& tintArgb == other.tintArgb;
	}
}

package com.tommyknight.mapdecorator;

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.AbstractMap;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Catalogue of placeable NPCs, loaded from npc_names.tsv (generated from the game cache's
 * npc definitions: id, name, standing animation). Only NPCs that have models and a real
 * name are included. The model parts and recolors themselves come from
 * {@code client.getNpcDefinition(id)} at runtime; the standing animation is bundled here
 * because the runtime NPCComposition doesn't expose it.
 */
final class NpcNames
{
	private static volatile Map<Integer, String> byId;
	private static volatile Map<Integer, Integer> idleAnimById;
	private static volatile Map<Integer, Integer> walkAnimById;
	/** Lowercased once at load time so search doesn't re-lowercase every name on every keystroke. */
	private static volatile Map<Integer, String> byIdLower;

	/** Name for the given npc id, or null if unknown. */
	static String name(int npcId)
	{
		load();
		return byId.get(npcId);
	}

	/** The npc's standing/idle animation id, or -1 if none is known. */
	static int idleAnimation(int npcId)
	{
		load();
		return idleAnimById.getOrDefault(npcId, -1);
	}

	/** The npc's walking animation id, or -1 if none is known. */
	static int walkAnimation(int npcId)
	{
		load();
		return walkAnimById.getOrDefault(npcId, -1);
	}

	/** All known npc ids, sorted ascending. */
	static List<Integer> knownIds()
	{
		load();
		List<Integer> ids = new ArrayList<>(byId.keySet());
		Collections.sort(ids);
		return ids;
	}

	/**
	 * Npc ids whose name contains the given substring (case-insensitive),
	 * ranked prefix-matches-first then by name length, capped at {@code limit} results.
	 */
	static List<Map.Entry<Integer, String>> search(String query, int limit)
	{
		load();
		String q = query.trim().toLowerCase(Locale.ROOT);
		if (q.isEmpty())
		{
			return List.of();
		}
		List<Map.Entry<Integer, String>> results = new ArrayList<>();
		for (Map.Entry<Integer, String> e : byId.entrySet())
		{
			if (byIdLower.get(e.getKey()).contains(q))
			{
				results.add(new AbstractMap.SimpleEntry<>(e.getKey(), e.getValue()));
			}
		}
		results.sort((a, b) ->
		{
			boolean aStarts = byIdLower.get(a.getKey()).startsWith(q);
			boolean bStarts = byIdLower.get(b.getKey()).startsWith(q);
			if (aStarts != bStarts)
			{
				return aStarts ? -1 : 1;
			}
			int lenCompare = Integer.compare(a.getValue().length(), b.getValue().length());
			return lenCompare != 0 ? lenCompare : a.getValue().compareToIgnoreCase(b.getValue());
		});
		return results.size() > limit ? results.subList(0, limit) : results;
	}

	private static synchronized void load()
	{
		if (byId != null)
		{
			return;
		}
		Map<Integer, String> names = new HashMap<>();
		Map<Integer, Integer> idles = new HashMap<>();
		Map<Integer, Integer> walks = new HashMap<>();
		Map<Integer, String> lower = new HashMap<>();
		try (InputStream in = NpcNames.class.getResourceAsStream("npc_names.tsv");
			BufferedReader br = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = br.readLine()) != null)
			{
				String[] parts = line.split("\t", 4);
				if (parts.length < 2)
				{
					continue;
				}
				int id = Integer.parseInt(parts[0]);
				if (id <= 0)
				{
					// id 0 collides with the "no npc" default in saved decorations
					continue;
				}
				names.put(id, parts[1]);
				lower.put(id, parts[1].toLowerCase(Locale.ROOT));
				try
				{
					if (parts.length >= 3)
					{
						idles.put(id, Integer.parseInt(parts[2]));
					}
					if (parts.length >= 4)
					{
						walks.put(id, Integer.parseInt(parts[3]));
					}
				}
				catch (NumberFormatException ignored)
				{
				}
			}
		}
		catch (Exception e)
		{
			// missing or malformed resource: npc selection just finds nothing
		}
		byId = names;
		idleAnimById = idles;
		walkAnimById = walks;
		byIdLower = lower;
	}

	private NpcNames()
	{
	}
}

