/**
 * Swing component that displays a software-rendered 3D model preview.
 * Drag left/right to rotate. Updates asynchronously when the object ID changes.
 */
class ModelPreviewComponent extends JPanel
{
	private static final int SIZE = 200;

	/** Background options by menu label; insertion order is menu order. */
	private static final Map<String, Color> BACKGROUNDS = new LinkedHashMap<>();
	static
	{
		BACKGROUNDS.put("None", ModelRenderer.DEFAULT_BG);
		BACKGROUNDS.put("Black", Color.BLACK);
		BACKGROUNDS.put("White", Color.WHITE);
		BACKGROUNDS.put("Green", new Color(0, 200, 0));
		BACKGROUNDS.put("Skybox", new Color(135, 206, 235));
	}

	private final ModelRenderer renderer = new ModelRenderer();
	private final JButton menuButton;
	private final JButton undoButton;
	private final JButton redoButton;
	private final JButton clearButton;
	private boolean canUndo;
	private boolean canRedo;
	private Runnable undoAction;
	private Runnable redoAction;
	private Runnable clearAction;
	private BufferedImage currentImage;
	private Consumer<String> backgroundSaver;
	// Resolves a texture id to its average RGB (client-thread only, like setModel itself)
	private IntFunction<Integer> textureColorResolver;

	private int dragStartX;
	private int dragStartY;
	private float yaw = 0.8f;
	private float pitch = (float) Math.toRadians(22);
	private float zoom = 1.0f;
	private float offsetX = 0;
	private float offsetY = 0;
	private boolean isPanning = false;

	ModelPreviewComponent()
	{
		setPreferredSize(new Dimension(SIZE, SIZE));
		setMinimumSize(new Dimension(SIZE, SIZE));
		setBackground(ModelRenderer.DEFAULT_BG);
		setLayout(null);

		// Background-color menu, overlaid in the top-left corner
		menuButton = new JButton()
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				Graphics2D g2 = (Graphics2D) g;
				g2.setColor(new Color(0, 0, 0, 140));
				g2.fillRect(0, 0, getWidth(), getHeight());
				g2.setColor(Color.WHITE);
				int barWidth = getWidth() - 8;
				int x = 4;
				g2.fillRect(x, getHeight() / 2 - 5, barWidth, 2);
				g2.fillRect(x, getHeight() / 2 - 1, barWidth, 2);
				g2.fillRect(x, getHeight() / 2 + 3, barWidth, 2);
			}
		};
		menuButton.setContentAreaFilled(false);
		menuButton.setBorderPainted(false);
		menuButton.setFocusPainted(false);
		menuButton.setOpaque(false);
		menuButton.setBounds(0, 0, 20, 18);
		menuButton.setToolTipText("Preview background colour");
		menuButton.addActionListener(e -> showBackgroundMenu());
		add(menuButton);

		// Undo / redo squares in the bottom-left corner
		undoButton = overlayArrowButton(true);
		undoButton.setBounds(0, SIZE - 18, 20, 18);
		undoButton.setToolTipText("Undo your last change");
		undoButton.addActionListener(e ->
		{
			if (canUndo && undoAction != null)
			{
				undoAction.run();
			}
		});
		add(undoButton);

		redoButton = overlayArrowButton(false);
		redoButton.setBounds(24, SIZE - 18, 20, 18);
		redoButton.setToolTipText("Redo what you just undid");
		redoButton.addActionListener(e ->
		{
			if (canRedo && redoAction != null)
			{
				redoAction.run();
			}
		});
		add(redoButton);

		// Reset-geometry square, right of undo/redo
		clearButton = overlayXButton();
		clearButton.setBounds(48, SIZE - 18, 20, 18);
		clearButton.setToolTipText("Reset offset, scale, rotation, height, tint and mirror");
		clearButton.addActionListener(e ->
		{
			if (clearAction != null)
			{
				clearAction.run();
			}
		});
		add(clearButton);

		MouseAdapter drag = new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				dragStartX = e.getX();
				dragStartY = e.getY();
				isPanning = SwingUtilities.isRightMouseButton(e) || e.isShiftDown();
			}

			@Override
			public void mouseDragged(MouseEvent e)
			{
				int dx = e.getX() - dragStartX;
				int dy = e.getY() - dragStartY;
				if (isPanning)
				{
					offsetX += dx;
					offsetY += dy;
				}
				else
				{
					yaw += dx * 0.015f;
					pitch += dy * 0.015f;
					pitch = Math.max(-(float) Math.PI / 2, Math.min((float) Math.PI / 2, pitch));
				}
				dragStartX = e.getX();
				dragStartY = e.getY();
				rerender();
			}
		};

		addMouseListener(drag);
		addMouseMotionListener(drag);
		addMouseWheelListener((MouseWheelEvent e) ->
		{
			zoom *= (float) Math.pow(1.1, -e.getPreciseWheelRotation());
			zoom = Math.max(0.2f, Math.min(5.0f, zoom));
			rerender();
		});
	}

	/** Update yaw and re-render. Safe to call from any thread. */
	void setYaw(float yaw)
	{
		this.yaw = yaw;
		rerender();
	}

	/** A small translucent square with a bold left/right arrow, greyed out while unavailable. */
	private JButton overlayArrowButton(boolean left)
	{
		JButton btn = new JButton()
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				Graphics2D g2 = (Graphics2D) g;
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				g2.setColor(new Color(0, 0, 0, 140));
				g2.fillRect(0, 0, getWidth(), getHeight());
				boolean available = left ? canUndo : canRedo;
				g2.setColor(available ? Color.WHITE : new Color(255, 255, 255, 80));
				g2.setStroke(new BasicStroke(2.2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				int cy = getHeight() / 2;
				int tip = left ? 6 : getWidth() - 6;
				int tail = left ? getWidth() - 6 : 6;
				int barb = left ? tip + 4 : tip - 4;
				g2.drawLine(tail, cy, tip, cy);
				g2.drawLine(tip, cy, barb, cy - 4);
				g2.drawLine(tip, cy, barb, cy + 4);
			}
		};
		btn.setContentAreaFilled(false);
		btn.setBorderPainted(false);
		btn.setFocusPainted(false);
		btn.setOpaque(false);
		return btn;
	}

	/** A small translucent square with a bold X, for the reset-geometry action. */
	private JButton overlayXButton()
	{
		JButton btn = new JButton()
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				Graphics2D g2 = (Graphics2D) g;
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				g2.setColor(new Color(0, 0, 0, 140));
				g2.fillRect(0, 0, getWidth(), getHeight());
				g2.setColor(Color.WHITE);
				g2.setStroke(new BasicStroke(2.2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				int pad = 6;
				g2.drawLine(pad, pad, getWidth() - pad, getHeight() - pad);
				g2.drawLine(getWidth() - pad, pad, pad, getHeight() - pad);
			}
		};
		btn.setContentAreaFilled(false);
		btn.setBorderPainted(false);
		btn.setFocusPainted(false);
		btn.setOpaque(false);
		return btn;
	}

	/** Wires the undo/redo squares to the plugin. */
	void initUndoRedo(Runnable undo, Runnable redo)
	{
		undoAction = undo;
		redoAction = redo;
	}

	/** Wires the reset-geometry square to the panel. */
	void initClear(Runnable clear)
	{
		clearAction = clear;
	}

	/** Updates which of the undo/redo squares draw as available. Call on the EDT. */
	void setUndoRedoState(boolean canUndo, boolean canRedo)
	{
		this.canUndo = canUndo;
		this.canRedo = canRedo;
		undoButton.repaint();
		redoButton.repaint();
	}

	/** Restores the saved background choice and registers where future choices are persisted. */
	void initBackground(String savedName, Consumer<String> saver)
	{
		Color color = savedName != null ? BACKGROUNDS.get(savedName) : null;
		if (color != null)
		{
			setBackgroundColor(color);
		}
		backgroundSaver = saver;
	}

	void setTextureColorResolver(IntFunction<Integer> resolver)
	{
		textureColorResolver = resolver;
	}

	private void showBackgroundMenu()
	{
		JPopupMenu menu = new JPopupMenu();
		for (Map.Entry<String, Color> entry : BACKGROUNDS.entrySet())
		{
			JMenuItem item = new JMenuItem(entry.getKey());
			item.addActionListener(e ->
			{
				setBackgroundColor(entry.getValue());
				if (backgroundSaver != null)
				{
					backgroundSaver.accept(entry.getKey());
				}
			});
			menu.add(item);
		}
		menu.show(menuButton, 0, menuButton.getHeight());
	}

	/** Changes the preview backdrop. Safe to call on the EDT (menu clicks always are). */
	private void setBackgroundColor(Color color)
	{
		setBackground(color);
		renderer.setBackgroundColor(color);
		if (renderer.hasModel())
		{
			rerender();
		}
		else
		{
			repaint();
		}
	}

	/**
	 * Load model data and render the first frame.
	 * Must be called on the client thread (model data extraction requirement).
	 * Schedules an EDT repaint when done.
	 */
	void setModel(ModelData model)
	{
		if (model == null)
		{
			renderer.clear();
			currentImage = null;
			SwingUtilities.invokeLater(this::repaint);
			return;
		}
		offsetX = 0;
		offsetY = 0;
		renderer.loadModel(model, textureColorResolver);
		BufferedImage img = renderer.render(SIZE, SIZE, yaw, pitch, zoom, offsetX, offsetY);
		SwingUtilities.invokeLater(() ->
		{
			currentImage = img;
			repaint();
		});
	}

	/** Redraw with the current yaw. Safe to call on any thread. */
	private void rerender()
	{
		if (!renderer.hasModel())
		{
			return;
		}
		BufferedImage img = renderer.render(SIZE, SIZE, yaw, pitch, zoom, offsetX, offsetY);
		SwingUtilities.invokeLater(() ->
		{
			currentImage = img;
			repaint();
		});
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);
		if (currentImage != null)
		{
			g.drawImage(currentImage, 0, 0, null);
		}
		else
		{
			g.setColor(getBackground());
			g.fillRect(0, 0, getWidth(), getHeight());
			g.setColor(Color.DARK_GRAY);
			String msg = "No model";
			int mx = (getWidth() - g.getFontMetrics().stringWidth(msg)) / 2;
			int my = getHeight() / 2;
			g.drawString(msg, mx, my);
		}
	}
}

package com.tommyknight.mapdecorator;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.function.IntFunction;
import net.runelite.api.ModelData;

/**
 * Software-renders a RuneLite Model to a BufferedImage.
 *
 * Uses unlit face HSL colors + flat shading from a fixed light direction.
 * getFaceColors1/2/3() are palette indices, not usable without the game palette,
 * so getUnlitFaceColors() (short[] Jagex HSL) is used instead.
 */
class ModelRenderer
{
	static final Color DEFAULT_BG = new Color(28, 28, 36);

	private volatile Color background = DEFAULT_BG;

	// Fixed light direction (normalized)
	private static final float LX = 0.5f, LY = -0.8f, LZ = 0.35f;
	private static final float LLEN = (float) Math.sqrt(LX * LX + LY * LY + LZ * LZ);

	/** Immutable per-model data, swapped atomically so render() never sees a half-loaded model. */
	private static final class Snapshot
	{
		final float[] vx, vy, vz;
		final int[] fi1, fi2, fi3;
		final int faceCount;
		final int[] baseRgb; // per-face base RGB from unlit HSL (or texture average for textured faces)
		final int[] alpha;   // per-face opacity, 0-255

		Snapshot(float[] vx, float[] vy, float[] vz, int[] fi1, int[] fi2, int[] fi3, int faceCount, int[] baseRgb, int[] alpha)
		{
			this.vx = vx;
			this.vy = vy;
			this.vz = vz;
			this.fi1 = fi1;
			this.fi2 = fi2;
			this.fi3 = fi3;
			this.faceCount = faceCount;
			this.baseRgb = baseRgb;
			this.alpha = alpha;
		}
	}

	private volatile Snapshot snapshot;

	boolean hasModel()
	{
		return snapshot != null;
	}

	/**
	 * Extract data from the model. Must be called on the client thread.
	 *
	 * @param textureRgb resolves a game texture id to its average RGB, so textured faces
	 *                   (whose face color is a meaningless placeholder â€” e.g. tree canopies)
	 *                   render in roughly the right color instead of grey; may be null,
	 *                   and may return null for unloaded textures (falls back to the HSL color)
	 */
	void loadModel(ModelData model, IntFunction<Integer> textureRgb)
	{
		float[] vx = model.getVerticesX();
		float[] vy = model.getVerticesY();
		float[] vz = model.getVerticesZ();
		int[] fi1 = model.getFaceIndices1();
		int[] fi2 = model.getFaceIndices2();
		int[] fi3 = model.getFaceIndices3();
		int faceCount = model.getFaceCount();

		short[] unlitColors = model.getFaceColors();
		short[] faceTextures = model.getFaceTextures();
		byte[] faceTransparencies = model.getFaceTransparencies();
		int[] baseRgb = new int[faceCount];
		int[] alpha = new int[faceCount];
		for (int i = 0; i < faceCount; i++)
		{
			Integer texAvg = null;
			if (faceTextures != null && i < faceTextures.length && faceTextures[i] != -1 && textureRgb != null)
			{
				texAvg = textureRgb.apply(faceTextures[i]);
			}
			if (texAvg != null)
			{
				baseRgb[i] = texAvg;
			}
			else
			{
				int hsl = (unlitColors != null && i < unlitColors.length)
					? (unlitColors[i] & 0xFFFF)
					: 0x3F60; // neutral grey fallback
				baseRgb[i] = jagexHslToRgb(hsl);
			}
			alpha[i] = (faceTransparencies != null && i < faceTransparencies.length)
				? 255 - (faceTransparencies[i] & 0xFF)
				: 255;
		}

		snapshot = new Snapshot(vx, vy, vz, fi1, fi2, fi3, faceCount, baseRgb, alpha);
	}

	void clear()
	{
		snapshot = null;
	}

	void setBackgroundColor(Color color)
	{
		background = color;
	}

	/**
	 * Render the loaded model to a new BufferedImage.
	 * Safe to call on any thread after loadModel() has finished.
	 *
	 * @param yaw rotation around the Y axis, in radians
	 */
	BufferedImage render(int w, int h, float yaw, float pitch, float zoom, float offsetX, float offsetY)
	{
		final Snapshot s = snapshot;
		float cosPitch = (float) Math.cos(pitch);
		float sinPitch = (float) Math.sin(pitch);
		BufferedImage img = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		if (s == null)
		{
			return img;
		}

		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(background);
		g.fillRect(0, 0, w, h);

		// Auto-scale: fit the model's bounding sphere to 80% of the smaller dimension
		float maxR = 1;
		for (int i = 0; i < s.vx.length; i++)
		{
			maxR = Math.max(maxR, Math.abs(s.vx[i]));
			maxR = Math.max(maxR, Math.abs(s.vy[i]));
			maxR = Math.max(maxR, Math.abs(s.vz[i]));
		}
		float scale = Math.min(w, h) * 0.4f / maxR * zoom;
		float cx = w * 0.5f + offsetX;
		float cy = h * 0.5f + offsetY;

		float cosY = (float) Math.cos(yaw);
		float sinY = (float) Math.sin(yaw);

		// Project all vertices
		int n = s.vx.length;
		float[] sx = new float[n];
		float[] sy = new float[n];
		float[] sz = new float[n];
		float[] wx = new float[n]; // world-space X after yaw only (for normals)
		float[] wy = new float[n];
		float[] wz = new float[n];

		for (int i = 0; i < n; i++)
		{
			// Y-axis rotation (yaw)
			float rx = s.vx[i] * cosY + s.vz[i] * sinY;
			float ry = s.vy[i];
			float rz = -s.vx[i] * sinY + s.vz[i] * cosY;

			// X-axis rotation (pitch)
			float rx2 = rx;
			float ry2 = ry * cosPitch - rz * sinPitch;
			float rz2 = ry * sinPitch + rz * cosPitch;

			wx[i] = rx2;
			wy[i] = ry2;
			wz[i] = rz2;

			// OSRS model Y is positive-downward, map directly (no negation).
			sx[i] = cx + rx2 * scale;
			sy[i] = cy + ry2 * scale;
			sz[i] = rz2;
		}

		// Painter's algorithm: sort faces back-to-front by average Z
		Integer[] order = new Integer[s.faceCount];
		for (int i = 0; i < s.faceCount; i++)
		{
			order[i] = i;
		}
		Arrays.sort(order, (a, b) ->
		{
			float za = (sz[s.fi1[a]] + sz[s.fi2[a]] + sz[s.fi3[a]]);
			float zb = (sz[s.fi1[b]] + sz[s.fi2[b]] + sz[s.fi3[b]]);
			return Float.compare(zb, za); // largest Z (furthest back) drawn first
		});

		int[] px = new int[3];
		int[] py = new int[3];

		for (int fi : order)
		{
			int a = s.fi1[fi], b = s.fi2[fi], c = s.fi3[fi];

			if (s.alpha[fi] <= 8)
			{
				continue; // effectively invisible
			}

			// Screen-space signed area â€” skip backfaces
			float area = (sx[b] - sx[a]) * (sy[c] - sy[a]) - (sy[b] - sy[a]) * (sx[c] - sx[a]);
			if (area >= 0)
			{
				continue; // back-facing
			}

			// World-space face normal (for lighting)
			float e1x = wx[b] - wx[a], e1y = wy[b] - wy[a], e1z = wz[b] - wz[a];
			float e2x = wx[c] - wx[a], e2y = wy[c] - wy[a], e2z = wz[c] - wz[a];
			float nx = e1y * e2z - e1z * e2y;
			float ny = e1z * e2x - e1x * e2z;
			float nz = e1x * e2y - e1y * e2x;
			float nlen = (float) Math.sqrt(nx * nx + ny * ny + nz * nz);
			if (nlen == 0)
			{
				continue;
			}
			nx /= nlen;
			ny /= nlen;
			nz /= nlen;

			float dot = Math.max(0, (nx * LX + ny * LY + nz * LZ) / LLEN);
			float brightness = 0.30f + 0.70f * dot; // 30% ambient + 70% diffuse

			int base = s.baseRgb[fi];
			int r = clamp((int) (((base >> 16) & 0xFF) * brightness));
			int gr = clamp((int) (((base >> 8) & 0xFF) * brightness));
			int bl = clamp((int) ((base & 0xFF) * brightness));

			px[0] = (int) sx[a]; px[1] = (int) sx[b]; px[2] = (int) sx[c];
			py[0] = (int) sy[a]; py[1] = (int) sy[b]; py[2] = (int) sy[c];

			g.setColor(new Color(r, gr, bl, s.alpha[fi]));
			g.fillPolygon(px, py, 3);
			if (s.alpha[fi] == 255)
			{
				// Antialiased fills leave hairline background seams between adjacent triangles;
				// outlining each opaque face in its own color covers them.
				g.drawPolygon(px, py, 3);
			}
		}

		g.dispose();
		return img;
	}

	// â”€â”€ Color conversion â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

	/**
	 * Convert Jagex packed HSL (6-bit hue, 3-bit saturation, 7-bit luminance) to sRGB.
	 * JagexColor only provides rgbToHSL; this is the inverse.
	 */
	static int jagexHslToRgb(int hsl)
	{
		float h = ((hsl >> 10) & 63) / 63f;
		float s = ((hsl >> 7) & 7) / 7f;
		float l = (hsl & 127) / 127f;
		return hslToRgb(h, s, l);
	}

	private static int hslToRgb(float h, float s, float l)
	{
		float c = (1 - Math.abs(2 * l - 1)) * s;
		float x = c * (1 - Math.abs((h * 6 % 2) - 1));
		float m = l - c / 2;

		float r, g, b;
		int hi = (int) (h * 6) % 6;
		switch (hi)
		{
			case 0: r = c; g = x; b = 0; break;
			case 1: r = x; g = c; b = 0; break;
			case 2: r = 0; g = c; b = x; break;
			case 3: r = 0; g = x; b = c; break;
			case 4: r = x; g = 0; b = c; break;
			default: r = c; g = 0; b = x; break;
		}

		return clamp((int) ((r + m) * 255)) << 16
			| clamp((int) ((g + m) * 255)) << 8
			| clamp((int) ((b + m) * 255));
	}

	private static int clamp(int v)
	{
		return Math.max(0, Math.min(255, v));
	}
}

package com.tommyknight.mapdecorator;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

@Data
@AllArgsConstructor
@NoArgsConstructor
class Favourite
{
	int objectId;
	String name;
	/** Looping animation sequence id; <= 0 means none. Absent in pre-1.1 saves (defaults to 0). */
	int animationId;
	/** NPC id placed instead of objectId; <= 0 means a plain model. Absent in pre-1.1 saves (defaults to 0). */
	int npcId;
	/** Placement orientation (S=0, W=512, N=1024, E=1536). Absent in pre-1.1 saves (defaults to 0 = south). */
	int orientation;
	/** Vertical nudge; positive = up. Absent in pre-1.1 saves (defaults to 0). */
	int heightOffset;
	/** Sub-tile nudge, east-west. Absent in pre-1.1 saves (defaults to 0). */
	int offsetX;
	/** Sub-tile nudge, north-south. Absent in pre-1.1 saves (defaults to 0). */
	int offsetY;
	/** Size adjustment in percent, 0 = normal. Absent in pre-1.1 saves (defaults to 0). */
	int scale;
	/** Placed NPCs wander a few tiles from where they are put. Absent in pre-1.1 saves (defaults to false). */
	boolean roam;
	/** Flipped left-to-right. Absent in pre-1.2 saves (defaults to false). */
	boolean mirror;
	/** Tint colour with alpha as strength; alpha 0 = no tint. Absent in pre-1.2 saves (defaults to 0). */
	int tintArgb;
}

package com.tommyknight.mapdecorator;

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.AbstractMap;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Lookup of animation sequence ids to their gameval constant names, loaded from
 * animation_names.tsv (generated from net.runelite.api.gameval.AnimationID).
 */
final class AnimationNames
{
	private static volatile Map<Integer, String> byId;
	private static volatile Map<String, Integer> byName;
	private static volatile Map<Integer, Integer> modelByAnimation;
	private static volatile Map<Integer, SearchEntry> searchCache;

	/** Precomputed once per attachable animation id, so search doesn't re-lowercase on every keystroke. */
	private static final class SearchEntry
	{
		final String display;
		final String displayLower;
		final String animNameLower;
		final String objectNameLower;

		SearchEntry(String display, String animNameLower, String objectNameLower)
		{
			this.display = display;
			this.displayLower = display.toLowerCase(Locale.ROOT);
			this.animNameLower = animNameLower;
			this.objectNameLower = objectNameLower;
		}
	}

	/** Name for the given animation id, or null if unknown. */
	static String name(int id)
	{
		load();
		return byId.get(id);
	}

	/** Animation id for the given constant name (case-insensitive), or null if unknown. */
	static Integer id(String name)
	{
		load();
		return byName.get(name.trim().toUpperCase(Locale.ROOT));
	}

	/**
	 * A model id known to use this animation as its ambient scenery animation
	 * (e.g. a fire's flame model), or null if the animation has no known scenery model.
	 * Sourced from a dev-time dump of the game cache's object definitions, so
	 * only covers scenery animations, not combat/player animations.
	 */
	static Integer modelFor(int animationId)
	{
		loadModels();
		return modelByAnimation.get(animationId);
	}

	/**
	 * Human-friendly name for the animation, matching what the search dropdown displays: the
	 * paired object's name when known (e.g. "Huge Spider"), falling back to the gameval constant
	 * name (e.g. "SPIDER_READY"), or null if neither is known.
	 */
	static String displayName(int animationId)
	{
		Integer modelId = modelFor(animationId);
		String objectName = modelId != null ? ObjectModelNames.name(modelId) : null;
		return objectName != null ? objectName : name(animationId);
	}

	/** All animation ids with a known scenery model (see {@link #modelFor}), sorted ascending. */
	static List<Integer> attachableIds()
	{
		loadModels();
		List<Integer> ids = new ArrayList<>(modelByAnimation.keySet());
		Collections.sort(ids);
		return ids;
	}

	/**
	 * Animation ids with a known scenery model (see {@link #modelFor}), matched against either the
	 * animation's own gameval constant name OR its paired object's human name (via {@link ObjectModelNames}).
	 * The constant names are things like "FIREBIRD_WALK" — rarely what someone would type — so matching
	 * the paired object's name too means searching "fire" actually finds fire animations. Displays the
	 * object name when known (falling back to the constant name), ranked prefix-matches-first then by
	 * display length, capped at {@code limit} results.
	 */
	static List<Map.Entry<Integer, String>> searchWithModel(String query, int limit)
	{
		load();
		loadModels();
		loadSearchCache();
		String q = query.trim().toLowerCase(Locale.ROOT);
		if (q.isEmpty())
		{
			return List.of();
		}
		List<Map.Entry<Integer, String>> results = new ArrayList<>();
		for (Map.Entry<Integer, SearchEntry> e : searchCache.entrySet())
		{
			SearchEntry se = e.getValue();
			boolean matches = se.animNameLower.contains(q)
				|| (se.objectNameLower != null && se.objectNameLower.contains(q));
			if (matches)
			{
				results.add(new AbstractMap.SimpleEntry<>(e.getKey(), se.display));
			}
		}
		results.sort((a, b) ->
		{
			SearchEntry sa = searchCache.get(a.getKey());
			SearchEntry sb = searchCache.get(b.getKey());
			boolean aStarts = sa.displayLower.startsWith(q);
			boolean bStarts = sb.displayLower.startsWith(q);
			if (aStarts != bStarts)
			{
				return aStarts ? -1 : 1;
			}
			int lenCompare = Integer.compare(a.getValue().length(), b.getValue().length());
			return lenCompare != 0 ? lenCompare : a.getValue().compareToIgnoreCase(b.getValue());
		});
		return results.size() > limit ? results.subList(0, limit) : results;
	}

	private static synchronized void load()
	{
		if (byId != null)
		{
			return;
		}
		Map<Integer, String> m = new HashMap<>();
		Map<String, Integer> r = new HashMap<>();
		try (InputStream in = AnimationNames.class.getResourceAsStream("animation_names.tsv");
			BufferedReader br = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = br.readLine()) != null)
			{
				int tab = line.indexOf('\t');
				if (tab <= 0)
				{
					continue;
				}
				int id = Integer.parseInt(line.substring(0, tab));
				String name = line.substring(tab + 1);
				m.put(id, name);
				r.putIfAbsent(name, id);
			}
		}
		catch (Exception e)
		{
			// missing or malformed resource: fall back to numeric display
		}
		byId = m;
		byName = r;
	}

	private static synchronized void loadModels()
	{
		if (modelByAnimation != null)
		{
			return;
		}
		Map<Integer, Integer> m = new HashMap<>();
		try (InputStream in = AnimationNames.class.getResourceAsStream("animation_models.tsv");
			BufferedReader br = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = br.readLine()) != null)
			{
				String[] parts = line.split("\t", 3);
				if (parts.length < 2)
				{
					continue;
				}
				m.put(Integer.parseInt(parts[0]), Integer.parseInt(parts[1]));
			}
		}
		catch (Exception e)
		{
			// missing or malformed resource: no auto-select available
		}
		modelByAnimation = m;
	}

	private static synchronized void loadSearchCache()
	{
		if (searchCache != null)
		{
			return;
		}
		Map<Integer, SearchEntry> cache = new HashMap<>();
		for (Map.Entry<Integer, Integer> e : modelByAnimation.entrySet())
		{
			int animId = e.getKey();
			int modelId = e.getValue();
			String animName = byId.getOrDefault(animId, String.valueOf(animId));
			String objectName = ObjectModelNames.name(modelId);
			String display = objectName != null ? objectName : animName;
			cache.put(animId, new SearchEntry(display, animName.toLowerCase(Locale.ROOT),
				objectName != null ? objectName.toLowerCase(Locale.ROOT) : null));
		}
		searchCache = cache;
	}

	private AnimationNames()
	{
	}
}

package com.tommyknight.mapdecorator;

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Lookup of model ids to the name of a game object known to use them, loaded from
 * object_models.tsv (generated from the Wiki/weirdgloop object database, which maps
 * object ids to names and their objectModels; here re-keyed by model id since that is
 * what the plugin places).
 */
final class ObjectModelNames
{
	private static volatile Map<Integer, String> byId;
	private static volatile Map<String, Integer> byName;
	/** Lowercased once at load time so search doesn't re-lowercase ~14k names on every keystroke. */
	private static volatile Map<Integer, String> byIdLower;

	/** Name of a known object using this model id, or null if unknown. */
	static String name(int modelId)
	{
		load();
		return byId.get(modelId);
	}

	/** Model id for the given object name (case-insensitive), or null if unknown. */
	static Integer id(String name)
	{
		load();
		return byName.get(name.trim().toUpperCase(Locale.ROOT));
	}

	/**
	 * Model ids whose object name contains the given substring (case-insensitive),
	 * ranked prefix-matches-first then by name length, capped at {@code limit} results.
	 */
	static List<Map.Entry<Integer, String>> search(String query, int limit)
	{
		load();
		String q = query.trim().toLowerCase(Locale.ROOT);
		if (q.isEmpty())
		{
			return List.of();
		}
		List<Map.Entry<Integer, String>> results = new ArrayList<>();
		for (Map.Entry<Integer, String> e : byId.entrySet())
		{
			if (byIdLower.get(e.getKey()).contains(q))
			{
				results.add(e);
			}
		}
		results.sort((a, b) ->
		{
			boolean aStarts = byIdLower.get(a.getKey()).startsWith(q);
			boolean bStarts = byIdLower.get(b.getKey()).startsWith(q);
			if (aStarts != bStarts)
			{
				return aStarts ? -1 : 1;
			}
			int lenCompare = Integer.compare(a.getValue().length(), b.getValue().length());
			return lenCompare != 0 ? lenCompare : a.getValue().compareToIgnoreCase(b.getValue());
		});
		return results.size() > limit ? results.subList(0, limit) : results;
	}

	private static synchronized void load()
	{
		if (byId != null)
		{
			return;
		}
		Map<Integer, String> m = new HashMap<>();
		Map<String, Integer> r = new HashMap<>();
		Map<Integer, String> lower = new HashMap<>();
		try (InputStream in = ObjectModelNames.class.getResourceAsStream("object_models.tsv");
			BufferedReader br = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = br.readLine()) != null)
			{
				int tab = line.indexOf('\t');
				if (tab <= 0)
				{
					continue;
				}
				int id = Integer.parseInt(line.substring(0, tab));
				// Some wiki names carry game menu markup, e.g. "<col=ffff00>Man</col>"
				String name = line.substring(tab + 1).replaceAll("<[^>]*>", "").trim();
				if (name.isEmpty())
				{
					continue;
				}
				m.put(id, name);
				r.putIfAbsent(name.toUpperCase(Locale.ROOT), id);
				lower.put(id, name.toLowerCase(Locale.ROOT));
			}
		}
		catch (Exception e)
		{
			// missing or malformed resource: fall back to numeric display
		}
		byId = m;
		byName = r;
		byIdLower = lower;
	}

	private ObjectModelNames()
	{
	}
}

package com.tommyknight.mapdecorator;

import javax.swing.SpinnerNumberModel;

/**
 * Degrees spinner that wraps at both ends instead of stopping, so holding an arrow key turns the
 * object continuously through full revolutions rather than sticking at 0 or 360.
 *
 * 360 is the same heading as 0, so stepping up from 359 lands on 0 rather than showing the same
 * angle twice. 360 stays a legal value â€” {@code orientationToDeg} rounds the topmost orientations
 * up to it â€” it just isn't a stop the arrows produce on their way round.
 */
class WrappingDegreeSpinnerModel extends SpinnerNumberModel
{
	private static final int FULL_TURN = 360;

	WrappingDegreeSpinnerModel(int initialValue)
	{
		super(initialValue, 0, FULL_TURN, 1);
	}

	@Override
	public Object getNextValue()
	{
		int deg = getNumber().intValue();
		return deg >= FULL_TURN - 1 ? 0 : deg + 1;
	}

	@Override
	public Object getPreviousValue()
	{
		int deg = getNumber().intValue();
		return deg <= 0 ? FULL_TURN - 1 : deg - 1;
	}
}

package com.tommyknight.mapdecorator;

import java.util.List;
import javax.swing.AbstractSpinnerModel;

/**
 * Spinner model that cycles only through a curated, sorted list of ids â€” so arrow-key/button
 * stepping jumps between actually-known entries (a named object, an animation with a model)
 * instead of every raw integer, most of which are unnamed junk between real ones. The value can
 * still be set to any integer via {@link #setValue} â€” manual entry, search selection, favourites,
 * and restoring a previously placed object/animation must all keep working even for ids outside
 * the curated list.
 *
 * An optional {@code floor} sentinel (e.g. -1 for the Animation box's "none") is treated as an
 * extra stop below the curated list; pass null if every value should be a real entry.
 */
class CuratedIdSpinnerModel extends AbstractSpinnerModel
{
	private final List<Integer> knownIds; // sorted ascending
	private final Integer floor;
	private int value;

	CuratedIdSpinnerModel(List<Integer> knownIds, Integer floor, int initialValue)
	{
		this.knownIds = knownIds;
		this.floor = floor;
		this.value = initialValue;
	}

	@Override
	public Object getValue()
	{
		return value;
	}

	@Override
	public void setValue(Object value)
	{
		// Always fire, even for a same-value commit, so the JFormattedTextField editor
		// re-syncs its displayed text after every commit attempt (typed or programmatic).
		this.value = (Integer) value;
		fireStateChanged();
	}

	@Override
	public Object getNextValue()
	{
		if (knownIds.isEmpty())
		{
			return null;
		}
		for (int id : knownIds)
		{
			if (id > value)
			{
				return id;
			}
		}
		// Past the last known id (or value is some stale/unrecognised number above them all,
		// e.g. from an old favourite) â€” wrap to the floor/start instead of permanently disabling
		// the up arrow.
		return floor != null ? floor : knownIds.get(0);
	}

	@Override
	public Object getPreviousValue()
	{
		if (knownIds.isEmpty())
		{
			return null;
		}
		if (floor != null && value <= floor)
		{
			return knownIds.get(knownIds.size() - 1);
		}
		Integer candidate = null;
		for (int id : knownIds)
		{
			if (id >= value)
			{
				break;
			}
			candidate = id;
		}
		if (candidate != null)
		{
			return candidate;
		}
		// value is below every known id (or a stale/unrecognised number smaller than all of
		// them) â€” step to the floor/end rather than disabling the down arrow.
		return floor != null ? floor : knownIds.get(knownIds.size() - 1);
	}
}
